(1, 1, 'QOLS00001', 'Abado 50 WP 20 X 20 X 10 gr', 'ABADO 50 WP merupakan fungisida sistemik dan protektif berbentuk tepung yang dapat disuspensikan untuk mengendalikan penyakit busuk buah kakao dan penyakit hawar daun pada tanaman kentang.\nBahan Aktif : Dimetomorf 50%\r\nIsi Bersih: 10 gr', 'ABADO_50WP_10GRAM.jpg', 7350, 7140, 7000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 16.3, 1, NULL, 0),
(2, 1, 'QOLS00002', 'Abado 50 WP 20 X 6 X 40 gr', 'ABADO 50 WP merupakan fungisida sistemik dan protektif berbentuk tepung yang dapat disuspensikan untuk mengendalikan penyakit busuk buah kakao dan penyakit hawar daun pada tanaman kentang.\nBahan Aktif : Dimetomorf 50%\r\nIsi Bersih: 40 gr', 'ABADO_50WP_40GRAM.jpg', 26250, 25500, 25000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 60.8, 1, NULL, 0),
(3, 9, 'QOLS00003', 'Abenz 22 EC 100 X 100 ml', 'ABENZ 22 EC merupakan insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning kecoklatan, untuk mengendalikan hama ulat grayak pada tanaman jagung dan penggerek buah pada tanaman tomat.\nBahan Aktif : Emamektin benzoat 22 g/l\r\nIsi Bersih: 100 ml', 'ABENZ_22EC_100ML.jpg', 72450, 70380, 69000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 126, 1, NULL, 0),
(4, 9, 'QOLS00004', 'Abenz 22 EC 40 X 250 ml', 'ABENZ 22 EC merupakan insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning kecoklatan, untuk mengendalikan hama ulat grayak pada tanaman jagung dan penggerek buah pada tanaman tomat.\nBahan Aktif : Emamektin benzoat 22 g/l\r\nIsi Bersih: 250 ml\r\n', 'ABENZ_22EC_250ML.jpg', 151200, 146880, 144000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 300, 1, NULL, 0),
(5, 15, 'QOLS00005', 'Abojo 60 WP 10 X 20 X 50 gr', 'ABOJO 60 WP merupakan moluskisida racun kontak berbentuk tepung yang dapat disuspensikan berwarna putih. ABOJO 60 WP dapat digunakan untuk mengendalikan hama siput murbei pada tanaman padi sawah.\nBahan Aktif: Fentin Asetat 60%\r\nIsi Bersih: 50 gr\r\n', 'ABOJO_60WP_50GRAM.jpg', 26250, 25500, 25000, 1000, 0, 'Pcs', 'Pcs', 'Box', '200', '1', 65.8, 1, NULL, 0),
(6, 15, 'QOLS00006', 'Abojo 60 WP 100 X 100 gr', 'ABOJO 60 WP merupakan moluskisida racun kontak berbentuk tepung yang dapat disuspensikan berwarna putih. ABOJO 60 WP dapat digunakan untuk mengendalikan hama siput murbei pada tanaman padi sawah.\nBahan Aktif: Fentin Asetat 60%\r\nIsi Bersih: 100 gr\r\n', 'ABOJO_60WP_100GRAM.jpg', 51975, 50490, 49500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 118, 1, NULL, 0),
(7, 1, 'QOLS00007', 'Acrobat WP 16 X 20 X 10 gr', 'ACROBAT 50 WP merupakan fungisida sistemik berbentuk tepung yang dapat disuspensikan berwarna putih digunakan untuk mengendalikan penyakit pada tanaman cabai, jagung, kentang, semangka, tembakau, dan tomat\nBahan aktif: Dimetomorf 50%\r\nIsi Bersih: 10 Gram', 'ACROBAT_50WP_10GRAM.jpg', 11550, 11220, 11000, 1000, 0, 'Pcs', 'Pcs', 'Box', '320', '1', 1, 1, NULL, 0),
(8, 1, 'QOLS00008', 'Acrobat WP 20 X 6 X 40 gr', 'ACROBAT 50 WP merupakan fungisida sistemik berbentuk tepung yang dapat disuspensikan berwarna putih digunakan untuk mengendalikan penyakit pada tanaman cabai, jagung, kentang, semangka, tembakau, dan tomat\nBahan aktif: Dimetomorf 50%\r\nIsi Bersih: 40 Gram\r\n', 'ACROBAT_50WP_40GRAM.jpg', 40950, 39780, 39000, 1000, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 55.4, 1, NULL, 0),
(9, 9, 'QOLS00009', 'Afonil 50 SC 100 X 100 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 100 ml\r\n', 'AFONIL_50SC_100ML.jpg', 32550, 31620, 31000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 154.8, 1, NULL, 0),
(10, 9, 'QOLS00010', 'Afonil 50 SC 100 X 50 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 50 ml\r\n', 'AFONIL_50SC_50ML.jpg', 19425, 18870, 18500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 78, 1, NULL, 0),
(11, 9, 'QOLS00011', 'Afonil 50 SC 20 X 500 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'AFONIL_50SC_500ML.jpg', 133350, 129540, 127000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 600, 1, NULL, 0),
(12, 9, 'QOLS00012', 'Afonil 50 SC 40 X 250 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'AFONIL_50SC_250ML.jpg', 74550, 72420, 71000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 336.3, 1, NULL, 0),
(13, 16, 'QOLS00013', 'Agridex 715 EC 12 X 1 ltr', 'AGRIDEX 715 EC adalah bahan perata dan penetran yang berbentuk larutan yang dapat diemulsikan, berwarna kuning jernih, untuk mengurangi tegangan permukaan larutan semprot Pestisida, meratakan dan meningkatkan daya penetrasi pestisida ke dalam jaringan tanaman\nBahan aktif : Minyak Parafinik 715 g/l\r\nIsi Bersih: 1 Liter\r\n', 'AGRIDEX_715EC_1LITER.jpg', 89775, 87210, 85500, 1000, 0, 'Pcs', 'Pcs', 'Box', '12', '1', 1, 1, NULL, 0),
(14, 9, 'QOLS00014', 'Agrimec 18 EC 40 X 250 ml', 'Agrimec merupakan Insektisida racun kontak berbentuk pekatan yang dapat diemulsikan, berwarna kuning pucat, untuk mengendalikan hama pada tanaman apel, cabai, jeruk, kacang hijau, kacang panjang, kelapa sawit, kentang, krisan, kubis, dan tomat.\nBahan Aktif:  18 g/l Abamektin\r\nKemasan : 250 ml\r\n', 'AGRIMEC_18EC_250ML.jpg', 99750, 96900, 95000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 302.5, 1, NULL, 0),
(15, 17, 'QOLS00015', 'Agristick 400 L 12 X 1 ltr', 'Agristick 400 L adalah merupakan bahan perata dan perekat non ionic berbentuk larutan tidak berwarna dengan, bahan aktif : Alkilaril poliglikol eter 400 g/L. Penyerapan perekat pestisida oleh petani akan tinggi menjelang menjelang hingga akhir hujan berlangsung. perekat penembus pestisida terbaik bisa anda buktikan dengan cara menyemprot daun talas atau tanaman bawang merah.\nBahan aktif: Alkilaril poliglikol eter 400 g/L\r\nIsi Bersih: 1 Liter\r\n', 'AGRISTICK_400L_1LITER.jpg', 100275, 97410, 95500, 1000, 0, 'Pcs', 'Pcs', 'Box', '12', '1', 1, 1, NULL, 0),
(16, 9, 'QOLS00016', 'Agus 500 SC 100 X 100 ml', 'AGUS 500 SC merupakan Insektisida yang juga bersifat akarisida bekerja sebagai racun kontak da perut, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air untuk mengendalikan hama serangga pada tanaman cabai.\nBahan Aktif: Diafentiuron 500 g/l\r\nIsi Bersih: 100 ml\r\n', 'AGUS_500SC_100ML.jpg', 65625, 63750, 62500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 152, 1, NULL, 0),
(17, 9, 'QOLS00017', 'Agus 500 SC 40 X 250 ml', 'AGUS 500 SC merupakan Insektisida yang juga bersifat akarisida bekerja sebagai racun kontak da perut, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air untuk mengendalikan hama serangga pada tanaman cabai.\nBahan Aktif: Diafentiuron 500 g/l\r\nIsi Bersih: 250 ml\r\n', 'AGUS_500SC_250ML.jpg', 149100, 144840, 142000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 331.3, 1, NULL, 0),
(18, 2, 'QOLS00018', 'Akalis 550 SC 10 X 1 ltr', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 1 Liter\r\n', 'AKALIS_550SC_1 LITER.jpg', 257250, 249900, 245000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 2, 1, NULL, 0),
(19, 2, 'QOLS00019', 'Akalis 550 SC 20 X 500 ml', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'AKALIS_550SC_500ML.jpg', 136500, 132600, 130000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(20, 2, 'QOLS00020', 'Akalis 550 SC 40 X 250 ml', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'AKALIS_550SC_250ML.jpg', 75075, 72930, 71500, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 542.5, 1, NULL, 0),
(21, 9, 'QOLS00021', 'Alika 247 ZC 100 X 50 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 50 ml', 'ALIKA_247ZC_50ML.jpg', 36488, 35445, 34750, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 77.5, 1, NULL, 0),
(22, 9, 'QOLS00022', 'Alika 247 ZC 40 X 250 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 250 ml', 'ALIKA_247ZC_250ML.jpg', 151200, 146880, 144000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 338.8, 1, NULL, 0),
(23, 9, 'QOLS00023', 'Alika 247 ZC 50 X 100 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 100 ml', 'ALIKA_247ZC_100ML.jpg', 64575, 62730, 61500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 144, 1, NULL, 0),
(24, 18, 'QOLS00024', 'Amira 10 X 500 ml', 'Dalam dunia pertanian, stres tanaman adalah salah satu penyebab utama penurunan hasil panen. Stres bisa disebabkan oleh cuaca ekstrem, kekeringan, serangan hama, atau ketidakseimbangan nutrisi. Untuk mengatasi tantangan ini, hadir Amira Anti-Stres—formulasi nutrisi tanaman yang dirancang khusus untuk memperkuat daya tahan tanaman dan meningkatkan penyerapan unsur hara.\nKandungan : Magnesium (MgO) 3,62 % w/w, Boron (B) 0.63% w/w & Mengandung 13% ekstrak rumput laut (Ascophylium nodosum)\r\nManfaat Amira :\r\n- Perlindungan maksimal tanaman dari stress\r\n- Tanaman kuat, tumbuh maksimal\r\nIsi Bersih: 500 ml\r\n', 'AMIRA_500ML.jpg', 126000, 122400, 120000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 750, 1, NULL, 0),
(25, 1, 'QOLS00025', 'Amistartop 325 SC 100 X 50 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 50ml', 'AMISTARTOP_325EC_50ML.jpg', 63525, 61710, 60500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 75.6, 1, NULL, 0),
(26, 1, 'QOLS00026', 'Amistartop 325 SC 20 X 250 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 250ml', 'AMISTARTOP_325EC_250ML.jpg', 279300, 271320, 266000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 332.5, 1, NULL, 0),
(27, 1, 'QOLS00027', 'Amistartop 325 SC 50 X 100 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 100ml', 'AMISTARTOP_325EC_100ML.jpg', 117075, 113730, 111500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 144.2, 1, NULL, 0),
(28, 1, 'QOLS00028', 'Amolin 300 EC 100 X 100 ml', 'Fungisida sistemik berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit busuk pelepah pada tanaman padi.\nBahan Aktif : Difekonazole 150 g/l + Propikonazole 150g/l\r\nIsi Bersih: 100 ml\r\n', 'AMOLIN_300EC_100ML.jpg', 54600, 53040, 52000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 139.1, 1, NULL, 0),
(29, 1, 'QOLS00029', 'Amolin 300 EC 40 X 250 ml', 'Fungisida sistemik berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit busuk pelepah pada tanaman padi.\nBahan Aktif : Difekonazole 150 g/l + Propikonazole 150g/l\r\nIsi Bersih: 250 ml\r\n', 'AMOLIN_300EC_250ML.jpg', 128100, 124440, 122000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 336.5, 1, NULL, 0),
(30, 9, 'QOLS00030', 'Amuron 70 EC 100 X 100 ml', 'AMURON 70 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening digunakan untuk mengendalikan hama ulat penggerek buah pada tanaman cabai.\nBahan Aktif : Heksaflumuron 50g/l + Emamektin benzoat 20g/l\r\nIsi Bersih: 100 ml', 'AMURON_70EC_100ML.jpg', 63000, 61200, 60000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 131, 1, NULL, 0),
(31, 9, 'QOLS00031', 'Amuron 70 EC 40 X 250 ml', 'AMURON 70 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening digunakan untuk mengendalikan hama ulat penggerek buah pada tanaman cabai.\nBahan Aktif : Heksaflumuron 50g/l + Emamektin benzoat 20g/l\r\nIsi Bersih: 250 ml', 'AMURON_70EC_250ML.jpg', 136500, 132600, 130000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 1, 1, NULL, 0),
(32, 9, 'QOLS00032', 'Android 72 EC 20 X 200 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 200 ml\r\n', 'ANDROID_72EC_200ML.jpg', 118125, 114750, 112500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(33, 9, 'QOLS00033', 'Android 72 EC 20 X 400 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 400 ml\r\n', 'ANDROID_72EC_400ML.jpg', 231000, 224400, 220000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 533, 1, NULL, 0),
(34, 9, 'QOLS00034', 'Android 72 EC 50 X 80 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 80 ml\r\n', 'ANDROID_72EC_80ML.jpg', 53550, 52020, 51000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 122, 1, NULL, 0),
(35, 1, 'QOLS00035', 'Anmi 100 SC 40 X 250 ml', 'ANMI 100 SC adalah fungisida sistemik berbahan aktif heksakonazol yang diformulasikan khusus untuk mengendalikan penyakit bercak ungu (Alternaria porri) pada tanaman bawang merah. Dengan formulasi SC (Suspension Concentrate), produk ini mudah diaplikasikan dan memberikan perlindungan menyeluruh terhadap tanaman.\nBahan Aktif : Heksakonazol 100 g/l\r\nIsi Bersih: 250 ml\r\n', 'ANMI_100SC_250ML.jpg', 59850, 58140, 57000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 348.5, 1, NULL, 0),
(36, 1, 'QOLS00036', 'Antracol 70 WP 12 X 1 kg', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\nBahan aktif : Propineb 70%\r\nIsi Bersih: 1 Kilogram\r\n', 'ANTRACOL_70WP_1KG.jpg', 158550, 154020, 151000, 1000, 0, 'Pcs', 'Pcs', 'Box', '12', '1', 1, 1, NULL, 0),
(37, 1, 'QOLS00037', 'Antracol 70 WP 20 X 500 gr', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\nBahan aktif : Propineb 70%\r\nIsi Bersih: 500 gr\r\n', 'ANTRACOL_70WP_250GRAM.jpg', 82425, 80070, 78500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 575, 1, NULL, 0),
(38, 1, 'QOLS00038', 'Antracol 70 WP 40 X 250 gr', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\nBahan aktif : Propineb 70%\r\nIsi Bersih: 250 gram\r\n', 'ANTRACOL_70WP_500GRAM.jpg', 42000, 40800, 40000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 291.3, 1, NULL, 0),
(39, 1, 'QOLS00039', 'Anvil 50 SC 10 X 1 ltr', 'ANVIL 50SC merupakan Fungisida sistemik berbentuk suspensi, berwarna putih kecoklat-coklatan untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jambu mete, kacang tanah, karet, kedelai, kelapa sawit, kopi, padi, pisang, semangka, dan tomat\n\r\nBahan aktif : Heksakonazol 50 g/l\r\nIsi kemasan : 1 Liter', 'ANVIL_50SC_1LITER.jpg', 231000, 224400, 220000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(40, 1, 'QOLS00040', 'Anvil 50 SC 40 X 250 ml', 'ANVIL 50SC merupakan Fungisida sistemik berbentuk suspensi, berwarna putih kecoklat-coklatan untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jambu mete, kacang tanah, karet, kedelai, kelapa sawit, kopi, padi, pisang, semangka, dan tomat\n\r\nBahan aktif : Heksakonazol 50 g/l\r\nIsi kemasan : 250ml', 'ANVIL_50SC_250ML.jpg', 64575, 62730, 61500, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 324.25, 1, NULL, 0),
(41, 18, 'QOLS00041', 'A-PlusCal 20 X 250 gr', 'A-PlusCal merupakan pupuk daun berkualitas tinggi yang diformulasikan khusus untuk memenuhi kebutuhan tanaman akan kalsium tanpa menambahkan nitrogen. Dengan kandungan CaO 34%, Zinc (Zn) 1,6%, dan Boron (B) 0,6%, A-PlusCal menjadi solusi ideal bagi petani dalam menjaga kesehatan tanaman, terutama di musim hujan.\nKandungan : CaO : 34%, Zn : 1,6%, B : 0,6%\r\nIsi Bersih: 250 ml', 'A-PLUSCAL_250ML.jpg', 78750, 76500, 75000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 350, 1, NULL, 0),
(42, 2, 'QOLS00042', 'Arendi 20/10 WP 20 X 20 X 25 gr', 'ARENDI 20/10 WP merupakan Herbisida sistemik pra dan purna tumbuh berbentuk tepung yang dapat disuspensikan berwarna putih untuk mengendalikan gulma pada pertanaman padi\nBahan Aktif : Natrium bispiribak 20% + Etil pirazosulfuron 10%\r\nIsi Bersih: 25 gr\r\n', 'ARENDI_25GRAM.jpg', 27300, 26520, 26000, 1000, 0, 'Pcs', 'Pcs', 'Box', '400', '1', 34, 1, NULL, 0),
(43, 1, 'QOLS00043', 'Aslinya 75 WP 100 X 100 gr', 'ASLINYA 75 WP merupakan fungisida sistemik berbentuk tepung yang dapat di suspensikan berwarna jingga untuk mengendalikan penyakit blas, patah leher, blas daun, blas leher, kresek pada tanaman padi\nBahan Aktif : Trisiklazol 75%\r\nIsi Bersih: 100 gr\r\n', 'ASLINYA_75WP_100GRAM.jpg', 60900, 59160, 58000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 141.5, 1, NULL, 0),
(44, 1, 'QOLS00044', 'Aslinya 75 WP 20 X 20 X 25 gr', 'ASLINYA 75 WP merupakan fungisida sistemik berbentuk tepung yang dapat di suspensikan berwarna jingga untuk mengendalikan penyakit blas, patah leher, blas daun, blas leher, kresek pada tanaman padi\nBahan Aktif : Trisiklazol 75%\r\nIsi Bersih: 25 gr\r\n', 'ASLINYA_75WP_25GRAM.jpg', 15750, 15300, 15000, 1000, 0, 'Pcs', 'Pcs', 'Box', '400', '1', 35.3, 1, NULL, 0),
(45, 9, 'QOLS00045', 'Ayuna 50 EC 40 X 250 ml', 'AYUNA 50 EC adalah insektisida yang mengandung bahan aktif Klorfluazuron 50 g/l. Produk ini dirancang untuk mengendalikan hama Ulat Grayak (Spodoptera litura) pada tanaman. Bahan aktif yang bekerja dengan cara menghambat proses pembentukan kutikula pada hama, sehingga hama tidak dapat berkembang normal dan akhirnya mati. AYUNA 50 EC efektif digunakan untuk mengendalikan hama Ulat Grayak (Spodoptera litura), yang dapat menyebabkan kerusakan pada tanaman dengan memakan daun dan bagian tanaman lainnya.\nBahan Aktif : Klorfluazuron  50 g/I\r\nIsi Bersih: 250 ml\r\n', 'AYUNA_50EC_250ML.jpg', 92400, 89760, 88000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 313.8, 1, NULL, 0),
(46, 2, 'QOLS00046', 'Aziziah 300/10 SC 20 X 500 ml', 'Aziziah 300/10 SC adalah herbisida sistemik selektif yang digunakan untuk mengendalikan gulma pada tanaman jagung. Herbisida ini berbentuk pekatan suspensi (SC) berwarna putih dan bekerja secara efektif baik sebelum (pra tumbuh) maupun sesudah (purna tumbuh) gulma muncul.\nBahan Aktif : Atrazin 300 g/l dan Mesotrion 10 g/l.\r\nIsi Bersih: 500 ml\r\n', 'AZIZIAH_500ML.jpg', 159600, 155040, 152000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(47, 9, 'QOLS00047', 'Baycarb 500 EC 20 X 500 ml', 'Baycarb® 500 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna coklat jernih untuk mengendalikan hama pada tanaman jagung, kakao, padi dan teh.\nBahan aktif : Fenobucarb (BPMC) 500 g/l\r\nIsi Bersih: 500 ml\r\n', 'BAYCARB_500EC_500ML.jpg', 74813, 72675, 71250, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 596, 1, NULL, 0),
(48, 9, 'QOLS00048', 'Belt Expert 480 SC 20 X 250 ml', 'Belt Expert 480 SC Insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi, berwarna putih kekuningan, mengendalikan hama pada tanaman padi sawah dan jagung\nBahan Aktif : Flubendiamida 240 g/l + Fiakloprid 240 g/l\r\nIsi Bersih: 250 ml\r\n', 'BELT_EXPERT_480SC_250ML.jpg', 405825, 394230, 386500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 365, 1, NULL, 0),
(49, 1, 'QOLS00049', 'Bion M 1/48 WP 20 X 500 gr', 'Bion M merupakan Fungisida protektif yang berbentuk tepung yang dapat disuspensikan berwarna coklat kekuning-kuningan, untuk mengendalikan penyakit yang disebabkan oleh cendawan dan bakteri pada tanaman cabai, kentang, kubis dan tomat.\n\r\nBahan aktif : Asibenzolar-s-metil 1% + mankozeb 48%\r\nIsi kemasan : 500gr', 'BION_M_500GR.jpg', 188475, 183090, 179500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 611, 1, NULL, 0),
(50, 9, 'QOLS00050', 'Brasso 250 EC 20 X 250 ml', 'BRASSO 250 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan, berwarna merah kecoklatan, untuk mengendalikan hama pada tanaman Kakao, Cabai, dan Kedelai.\nBahan Aktif : Sipermetrin 250 g/l\r\nIsi Bersih: 250 ml\r\n', 'BRASSO_250EC_250ML.jpg', 50400, 48960, 48000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 315, 1, NULL, 0),
(51, 9, 'QOLS00051', 'Brasso 250 EC 20 X 400 ml', 'BRASSO 250 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan, berwarna merah kecoklatan, untuk mengendalikan hama pada tanaman Kakao, Cabai, dan Kedelai.\nBahan Aktif : Sipermetrin 250 g/l\r\nIsi Bersih: 400 ml\r\n', 'BRASSO_250EC_400ML.jpg', 74550, 72420, 71000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 511, 1, NULL, 0),
(52, 1, 'QOLS00052', 'Cabrio 250 EC 24 X 250 ml', 'CABRIO 250 EC merupakan Fungisida yang bersifat protektif dan kuratif berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit pada tanaman tomat, kentang dan bawang merah.\nBahan Aktif: Piraklostrobin 250 g/l\r\nIsi Bersih: 250 ml\r\n', 'CABRIO_250EC_250ML.jpg', 202650, 196860, 193000, 1000, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 345.8, 1, NULL, 0),
(53, 1, 'QOLS00053', 'Cabrio 250 EC 48 X 100 ml', 'CABRIO 250 EC merupakan Fungisida yang bersifat protektif dan kuratif berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit pada tanaman tomat, kentang dan bawang merah.\nBahan Aktif: Piraklostrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'CABRIO_250EC_100ML.jpg', 87675, 85170, 83500, 1000, 0, 'Pcs', 'Pcs', 'Box', '48', '1', 162.5, 1, NULL, 0),
(54, 2, 'QOLS00054', 'Calaris 550 SC 10 X 1 ltr', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 1 Liter', 'CALARIS_550SC_1LITER.jpg', 278250, 270300, 265000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(55, 2, 'QOLS00055', 'Calaris 550 SC 20 X 250 ml', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 250ml', 'CALARIS_550SC_250ML.jpg', 76650, 74460, 73000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 540, 1, NULL, 0),
(56, 2, 'QOLS00056', 'Calaris 550 SC 20 X 500 ml', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 500ml', 'CALARIS_550SC_500ML.jpg', 144900, 140760, 138000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(57, 9, 'QOLS00057', 'Confidor 200 SL 100 X 60 ml', 'Confidor 200 SL Insektisida sistemik racun kontak dan lambung berbentuk larutan dalam air, berwarna coklat jernih, untuk mengendalikan hama pada tanaman apel, cabai, jagung, jeruk, kacang panjang, kapas, kelapa sawit, kentang, ketimun, mangga, padi, semangka, teh, tembakau dan tomat\nBahan aktif : Imidakloprid 200 g/l\r\nIsi Bersih: 60 ml\r\n', 'CONFIDOR_200SL_60ML.jpg', 62738, 60945, 59750, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 99.2, 1, NULL, 0),
(58, 9, 'QOLS00058', 'Confidor Extra 350 SC 100 X 100 ml', 'CONFIDOR EXTRA® 350 SC Insektisida sistemik yang bekerja secara racun kontak dan lambung berbentuk pekatan suspensi yang larut dalam air berwarna putih untuk mengendalikan hama pada tanaman apel, cabai, jagung, jeruk, kacang panjang, kentang, mangga, mentimun, padi sawah, semangka, teh, tembakau dan tomat.\nBahan aktif : imidakloprid 350 g/l\r\nIsi Bersih: 100 ml\r\n', 'CONFIDOR_EXTRA_100ML.jpg', 98175, 95370, 93500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 149.2, 1, NULL, 0),
(59, 2, 'QOLS00059', 'Council Complete SC 300 50 X 100 ml', 'Council Complete® 300 SC Herbisida selektif, berbentuk pekatan suspensi berwarna putih kekuningan, bekerja secara sistemik dan digunakan untuk mengendalikan gulma pada pertanaman padi tanam pindah (TAPIN) dan tanam benih langsung (TABELA).\nBahan aktif : Triafamone 100 g/l + Tefuryltrione 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'COUNCIL_COMPLETE_100ML.jpg', 181125, 175950, 172500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 140, 1, NULL, 0),
(60, 2, 'QOLS00060', 'Council Complete SC 300 50 X 50 ml', 'Council Complete® 300 SC Herbisida selektif, berbentuk pekatan suspensi berwarna putih kekuningan, bekerja secara sistemik dan digunakan untuk mengendalikan gulma pada pertanaman padi tanam pindah (TAPIN) dan tanam benih langsung (TABELA).\nBahan aktif : Triafamone 100 g/l + Tefuryltrione 200 g/l\r\nIsi Bersih: 50 ml\r\n', 'COUNCIL_COMPLETE_50ML.jpg', 90300, 87720, 86000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 80, 1, NULL, 0),
(61, 9, 'QOLS00061', 'Curacron 500 EC 20 X 500 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 500ml', 'CURACRON_500EC_500ML.jpg', 143588, 139485, 136750, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 686, 1, NULL, 0),
(62, 9, 'QOLS00062', 'Curacron 500 EC 40 X 250 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 250ml', 'CURACRON_500EC_250ML.jpg', 73500, 71400, 70000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 356.5, 1, NULL, 0),
(63, 9, 'QOLS00063', 'Curacron 500 EC 50 X 100 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 100ml', 'CURACRON_500EC_100ML.jpg', 31500, 30600, 30000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 150.2, 1, NULL, 0),
(64, 9, 'QOLS00064', 'Cymbush 50 EC 100 X 100 ml', 'Cymbush merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat muda jernih, untuk mengendalikan hama-hama pada tanaman kedelai, kubis dan tembakau.\n\r\nBahan aktif : Sipermetrin 50 g/l\r\nIsi kemasan : 100ml', 'CYMBUSH_50EC_100ML.jpg', 21000, 20400, 20000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 122.4, 1, NULL, 0),
(65, 9, 'QOLS00065', 'Cymbush 50 EC 40 X 250 ml', 'Cymbush merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat muda jernih, untuk mengendalikan hama-hama pada tanaman kedelai, kubis dan tembakau.\nBahan aktif : Sipermetrin 50 g/l\r\nIsi kemasan : 250ml', 'CYMBUSH_50EC_250ML.jpg', 51450, 49980, 49000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 287.5, 1, NULL, 0),
(66, 9, 'QOLS00066', 'Decis 25 EC 100 X 100 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 100 ml\r\n', 'DECIS_25EC_100ML.jpg', 28875, 28050, 27500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 126.5, 1, NULL, 0),
(67, 9, 'QOLS00067', 'Decis 25 EC 100 X 50 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 50 ml\r\n', 'DECIS_25EC_50ML.jpg', 15908, 15453, 15150, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 77.5, 1, NULL, 0),
(68, 9, 'QOLS00068', 'Decis 25 EC 20 X 500 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 500 ml\r\n', 'DECIS_25EC_500ML.jpg', 130988, 127245, 124750, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 549.5, 1, NULL, 0),
(69, 9, 'QOLS00069', 'Decis 25 EC 40 X 250 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 250 ml\r\n', 'DECIS_25EC_250ML.jpg', 70613, 68595, 67250, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 301.75, 1, NULL, 0),
(70, 9, 'QOLS00070', 'Elestal Neo 54 WG 100 X 30 gr', 'Elestal Neo merupakan Insektisida racun kontak dan lambung berbentuk butiran yang dapat didispersikan dalam air yang bekerja dengan menghambat biosintesa lemak dan menyebabkan serangga menjadi lumpuh, berwarna coklat muda untuk mengendalikan hama di tanaman cabai dan tomat.  \n\r\nBahan aktif : Spiropidion 30% + acetamiprid 24%\r\nIsi kemasan : 30 Gram', 'ESTAL_NEO_30GRAM.jpg', 99750, 96900, 95000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 176, 1, NULL, 0),
(71, 9, 'QOLS00071', 'Elestal Neo 54 WG 20 X 150 gr', 'Elestal Neo merupakan Insektisida racun kontak dan lambung berbentuk butiran yang dapat didispersikan dalam air yang bekerja dengan menghambat biosintesa lemak dan menyebabkan serangga menjadi lumpuh, berwarna coklat muda untuk mengendalikan hama di tanaman cabai dan tomat.  \n\r\nBahan aktif : Spiropidion 30% + acetamiprid 24%\r\nIsi kemasan : 150 Gram', 'ESTAL_NEO_150GRAM.jpg', 425250, 413100, 405000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 640, 1, NULL, 0),
(72, 20, 'QOLS00072', 'Ethrel 480 SL 100 X 100 ml', 'ETHREL 480 SL merupakan zat pengatur tumbuh tanaman berbentuk larutan dalam air yang berwarna coklat jernih digunakan sebagai zat pengatur tumbuh tanaman pada tanaman Apel, Kedelai, Kopi, Nenas, Pisang, dan Tembakau\nBahan aktif : Etefon 480 g/l\r\nIsi Bersih: 100 ml\r\n', 'ETHREL_480SL_100ML.jpg', 44625, 43350, 42500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 156.5, 1, NULL, 0),
(73, 9, 'QOLS00073', 'Fenval 200 EC 15 X 1 ltr', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 1 Liter\r\n', 'FENVAL_200EC_1LITER.jpg', 142800, 138720, 136000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(74, 9, 'QOLS00074', 'Fenval 200 EC 20 X 250 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 250 ml\r\n', 'FENVAL_200EC_250ML.jpg', 35700, 34680, 34000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 315, 1, NULL, 0),
(75, 9, 'QOLS00075', 'Fenval 200 EC 20 X 500 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 500 ml\r\n', 'FENVAL_200EC_500ML.jpg', 73500, 71400, 70000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 589, 1, NULL, 0),
(76, 9, 'QOLS00076', 'Fenval 200 EC 50 X 100 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'FENVAL_200EC_100ML.jpg', 15750, 15300, 15000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 134.6, 1, NULL, 0),
(77, 1, 'QOLS00077', 'Filia 525 SE 100 X 50 ml', 'Filia merupakan fungisida protektif untuk mengendalikan penyakit blas Pyricularia oryzae pada tanaman padi. Dengan kombinasi dua bahan aktif pilihan yang do formulasi secara tepat, maka Filia 525 SE tidak saja mengendalikan penyakit blas yang sering terjadi pada tanaman padi seperti Ustilago, hawar pelepah, \"dirty panicle\" pada bulir tetapi juga membuat batang lebih kuat, enampilan daun dan tamana padi lebih hijau dan memberikan peningkatan hasil yang signfikan. Filia 525 SE juga dapat digunakan pada tanaman bawang merah untuk mengendalikan penyakit dan meningkatkan kualitas umbi serta hasil panen.\n\r\nBahan aktif : Trisiklazol 400 g/l + Propikonazol 125 g/l\r\nIsi kemasan : 50ml', 'FILIA_525SE_50ML.jpg', 30713, 29835, 29250, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 81.3, 1, NULL, 0),
(78, 1, 'QOLS00078', 'Filia 525 SE 20 X 250 ml', 'Filia merupakan fungisida protektif untuk mengendalikan penyakit blas Pyricularia oryzae pada tanaman padi. Dengan kombinasi dua bahan aktif pilihan yang do formulasi secara tepat, maka Filia 525 SE tidak saja mengendalikan penyakit blas yang sering terjadi pada tanaman padi seperti Ustilago, hawar pelepah, \"dirty panicle\" pada bulir tetapi juga membuat batang lebih kuat, enampilan daun dan tamana padi lebih hijau dan memberikan peningkatan hasil yang signfikan. Filia 525 SE juga dapat digunakan pada tanaman bawang merah untuk mengendalikan penyakit dan meningkatkan kualitas umbi serta hasil panen.\n\r\nBahan aktif : Trisiklazol 400 g/l + Propikonazol 125 g/l\r\nIsi kemasan : 250ml', 'FILIA_525SE_250ML.jpg', 133875, 130050, 127500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 354.5, 1, NULL, 0),
(79, 1, 'QOLS00079', 'Folirfos 400 SL 15 X 1 ltr', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 1 Liter\r\n', 'FOLIRFOS_400SL_1LITER.jpg', 99750, 96900, 95000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(80, 1, 'QOLS00080', 'Folirfos 400 SL 20 X 500 ml', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 500 ml\r\n', 'FOLIRFOS_400SL_500ML.jpg', 55125, 53550, 52500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 783, 1, NULL, 0),
(81, 1, 'QOLS00081', 'Folirfos 400 SL 4 X 5 ltr', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 5 Liter\r\n', 'FOLIRFOS_400SL_5LITER.jpg', 472500, 459000, 450000, 1000, 0, 'Pcs', 'Pcs', 'Box', '4', '1', 6, 1, NULL, 0),
(82, 19, 'QOLS00082', 'Forsil 20 X 250 ml', 'FORSIL merupakan pupuk mikro majemuk an-organik yang dapat terlarut sempurnadalam air. Forsil yang diperkaya silika yang dapat meningkatkan kualitas dan hasilpanen, selain itu juga berfungsi sebagai Biostimulant yang dapat melindungi tanaman dari serangan hama dan penyakit, kekeringan, serta perubahan cuaca\nKandungan Hara: Silika (SiO2) 20%, Seng (Zn) 0,25%, Molibdenum (Mo) 0,001%\r\nIsi Bersih: 250 ml\r\n', 'FORSIL_250ML.jpg', 58800, 57120, 56000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 400, 1, NULL, 0),
(83, 19, 'QOLS00083', 'Forsil 20 X 500 ml', 'FORSIL merupakan pupuk mikro majemuk an-organik yang dapat terlarut sempurnadalam air. Forsil yang diperkaya silika yang dapat meningkatkan kualitas dan hasilpanen, selain itu juga berfungsi sebagai Biostimulant yang dapat melindungi tanaman dari serangan hama dan penyakit, kekeringan, serta perubahan cuaca\nKandungan Hara: Silika (SiO2) 20%, Seng (Zn) 0,25%, Molibdenum (Mo) 0,001%\r\nIsi Bersih: 500 ml\r\n', 'FORSIL_500ML.jpg', 108675, 105570, 103500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 765, 1, NULL, 0),
(84, 1, 'QOLS00084', 'Insure Max 510 FS 100 X 25 ml', 'INSURE MAX 510 FS merupakan Fungisida sistemik yang bersifat protektif dan kuratif berbentuk pekatan suspensi berwarna merah muda digunakan untuk mengendalikan penyakit Bulai pada tanaman Jagung.\nBahan Aktif: Dimetomorf 500 g/l & Piraklostrobin 10 g/l\r\nIsi Bersih: 25 ml\r\n', 'INSURE_MAX_25ML.jpg', 35700, 34680, 34000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 49.1, 1, NULL, 0),
(85, 14, 'QOLS00085', 'Jagung ADV 132 20 X 1 kg', 'Jagung ADV 132 adalah benih jagung hibrida yang diproduksi oleh perusahaan Advanta Seeds Indonesia dengan nama produk ADV Montok. Benih ini dikenal karena toleransinya terhadap penyakit bulai dan rendemennya yang sangat tinggi. Tipe persilangan: Hibrida silang tunggal.Batang: Kokoh dan tahan dari kerobohan.Pengakaran: Dalam, memberikan stabilitas pada tanaman.Toleransi penyakit: Sangat toleran terhadap penyakit bulai dan busuk batang.Tongkol: Montok, terisi penuh hingga ujung, dan kelobot menutup dengan sempurna, sehingga tidak mudah busuk.Hasil panen: Rendemennya sangat tinggi, mencapai kurang lebih 85%.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_ADV_132_1KG.jpg', 93450, 90780, 89000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(86, 14, 'QOLS00086', 'Jagung DK 771 20 X 1 kg (Bayer)', 'Benih Jagung Hibrida Dekalb 771 Produksinya tinggi, juga tahan terhadap serangan penyakit bulai dan mampu menghasilkan jagung dengan tongkol lebih panjang dan besar. Benih jagung ini juga mudah ditanam di lahan datar, lereng gunung, ataupun di lahan-lahan marginal lainnya.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK771_1KG.jpg', 85050, 82620, 81000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(87, 14, 'QOLS00087', 'Jagung DK 9209C 20 X 1 kg (Bayer)', 'Jagung DK 9209C adalah benih jagung hibrida dari Bayer dengan keunggulan ketahanan terhadap penyakit bulai dan busuk batang, adaptasi luas di berbagai kondisi tanah, serta potensi hasil yang tinggi hingga 15,2 ton per hektare pipil kering, sehingga cocok untuk meningkatkan produktivitas petani. Benih ini menghasilkan tongkol yang besar dengan biji yang rapat dan dapat dipanen pada berbagai usia.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK9209C_1KG.jpg', 107100, 104040, 102000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(88, 14, 'QOLS00088', 'Jagung DK 95R 20 X 1 kg', 'DEKALB DK95R adalah Jagung Bioteknologi Tahan Roundup (glifosat), memungkinkan penggunaan herbisida berbasis glifosat tanpa merusak tanaman jagung.\nKeunggulan:\r\n- Tahan Herbisida Glyphosate: Mengurangi gulma secara efisien tanpa merusak tanaman.\r\n- Hasil Panen Tinggi: Teruji di lahan petani dengan produktivitas tinggi.\r\n- Kualitas Benih Terjamin: Diproduksi oleh Bayer, perusahaan global terpercaya di bidang pertanian.\r\n- Efisiensi Biaya: Mengurangi kebutuhan tenaga kerja dan biaya penyiangan manual.\r\n- Cocok untuk Wilayah Tropis: Telah diuji dan terbukti adaptif untuk kondisi Indonesia.\r\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK95R_1KG.jpg', 120000, 115000, 110000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(89, 14, 'QOLS00089', 'Jagung NK 212 20 X 1 kg', 'NK212 memiliki kemampuan beradaptasi di lahan tadah hujan (tegalan) dan lahan sawah dengan kondisi tanah yang marjinal serta kekurangan air. NK 212 adalah jagung yang mempunyai pertumbuhan awal sangat bagus, warna oranye, dan pengisian penuh. Serta benih jagung ini juga mudah beradptasi di berbagai kondisi lahan.\nPotensi Hasil: 10,8 Ton/Ha pipilan kering.\r\nRata-Rata Hasil: 9,5 Ton/Ha pipilan kering.\r\nUmur Panen: ± 101 HST\r\nKemasan: 1 kilogram', 'JAGUNG_NK212_1KG.jpg', 86625, 84150, 82500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(90, 14, 'QOLS00090', 'Jagung NK 212 BTGT 20 X 1 kg', 'NK212s | NK Pendekar Sakti adalah benih Jagung Hibrida Bioteknologi NK212s-Bt11GA21 yang sudah ditambahkan dengan beberapa kesaktian. NK Pendekar Sakti memiliki kesaktian (toleran) terhadap penyemprotan herbisida glyphosate murni dan juga sakti (tahan) terhadap serangan hama penggerek batang-Asian Corn Borer. Kesaktian yang dimiliki NK Pendekar Sakti menawarkan budidaya tanaman jagung yang lebih mudah dan murah, serta pastinya meningkatkan hasil bagi petani.\nPotensi Hasil: 11,8 Ton/Ha (KA 15%).\r\nRata-Rata Hasil: 9,0 Ton/Ha (KA 15%).\r\n Umur Panen: ± 103 HST\r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK212_SAKTI_1KG.jpg', 111300, 108120, 106000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(91, 14, 'QOLS00091', 'Jagung NK 7202 20 X 1 kg', 'NK7202 | NK JUARA memiliki kemampuan beradaptasi di lahan sawah. Benih NK Juara dapat ditanam oleh petani yang mempunyai masalah endemik penyakit bulai dan busuk batang, karena benih ini memiliki ketahanan terhadap penyakit tersebut. Selain itu benih ini juga memiliki potensi hasil yang tinggi, sehingga membuat petani aman dan menguntungkan dengan hasil tanam jagungnya.\nPotensi Hasil: 12,9 Ton/Ha.\r\nRata-Rata Hasil: 10,7 Ton/Ha.\r\nUmur Panen: ± 107 HST \r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK7202_JUARA_1KG.jpg', 101325, 98430, 96500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(92, 14, 'QOLS00092', 'Jagung NK 7328 20 X 1 kg', 'NK7328 | NK SUMO memiliki kemampuan beradaptasi di lahan tadah hujan (tegalan) dan untuk petani progressive. Benih ini memiliki tanaman yang Sumo dengan hasil yang Sumo. Petani tidak perlu khawatir tanaman rebah karena batang yang kokoh, serta pertumbuhan tanaman yang menarik yang disukai oleh petani jagung Indonesia.\nPotensi Hasil: 12,4 Ton/Ha (KA 15%). \r\nRata-Rata Hasil: 9,9 Ton/Ha (KA 15%). \r\nUmur Panen: ± 115 HST\r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK7328_1KG.jpg', 119175, 115770, 113500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(93, 14, 'QOLS00093', 'Jagung NK 7328 BTGT 20 X 1 kg', 'NK7328s | NK Sumo Sakti adalah benih Jagung Hibrida Bioteknologi NK7328s-Bt11GA21 dengan performa tanaman yang disukai petani, berbatang Kokoh, dan juga memiliki kesaktian tambahan dari varietas NK Sumo sebelumnya. Kesaktian yang dimiliki oleh NK Sumo Sakti adalah ketahanan terhadap penyemprotan herbisida jenis Glyphosate murni dan juga ketahanan terhadap serangan hama penggerek batang (Asian Corn Borer). Petani akan lebih mudah dalam membudidayakan jagung hibrida, lebih sedikit menggunakan pestisida untuk perawatan tanaman sehingga lebih menguntungkan, dan tentunya meningkatkan hasil bagi petani.\nPotensi Hasil: 11.5 Ton/Ha (KA 15%). \r\nRata-Rata Hasil: 9.0 Ton/Ha (KA 15%) \r\nUmur Panen: ± 105 HST\r\nKemasan: 1 Kilogram\r\n', '-', 140175, 136170, 133500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(94, 14, 'QOLS00094', 'Kubis Hibrida F1 Kaelo 30 X 15 gr', 'Kubis Hibrida F1 Kaelo adalah varietas kubis produk Seminis yang cocok untuk dataran rendah-menengah, memiliki umur panen genjah (sekitar 50-65 HST), menghasilkan krop bulat pipih, keras, dan padat dengan berat 1,5-2,5 kg, serta tahan penyakit akar gada, bercak daun, dan jamur. Kubis ini memiliki kemampuan adaptasi luas, tahan cuaca panas, dan cocok untuk pengangkutan jarak jauh karena tidak mudah pecah.\nIsi Bersih: 15 Gram\r\n', 'KUBIS_KAELO_15GRAM.jpg', 90300, 87720, 86000, 1000, 0, 'Pcs', 'Pcs', 'Box', '30', '1', 17, 1, NULL, 0),
(95, 1, 'QOLS00095', 'Luna Smart 250/250 SC 100 X 100 ml', 'Fungisida yang bersifat preventif, kuratif dan sistemik berbentuk pekatan suspensi yang larut dalam air berwarna putih keabu-abuan untuk mengendalikan penyakit-penyakit pada tanaman apel, bawang merah, cabai, jeruk, kakao, kentang, mangga, semangka dan tomat\nBahan aktif : Fluopiram 250 g/l + Trifloksistrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'LUNA_SMART_100ML.jpg', 142275, 138210, 135500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 151.5, 1, NULL, 0),
(96, 1, 'QOLS00096', 'Luna Smart 250/250 SC 50 X 100 ml', 'Fungisida yang bersifat preventif, kuratif dan sistemik berbentuk pekatan suspensi yang larut dalam air berwarna putih keabu-abuan untuk mengendalikan penyakit-penyakit pada tanaman apel, bawang merah, cabai, jeruk, kakao, kentang, mangga, semangka dan tomat\nBahan aktif : Fluopiram 250 g/l + Trifloksistrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'LUNA_SMART_100ML.jpg', 142275, 138210, 135500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 77, 1, NULL, 0);
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_2`, `price_3`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(97, 9, 'QOLS00097', 'Matador 25 EC 100 X 50 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 50 ml\r\n', 'MATADOR_25EC_50ML.jpg', 16485, 16014, 15700, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 67.1, 1, NULL, 0),
(98, 9, 'QOLS00098', 'Matador 25 EC 100 X 80 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 80 ml\r\n', 'MATADOR_25EC_80ML.jpg', 23363, 22695, 22250, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 102.8, 1, NULL, 0),
(99, 9, 'QOLS00099', 'Matador 25 EC 40 X 250 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 250 ml\r\n', 'MATADOR_25EC_250ML.jpg', 65888, 64005, 62750, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 285.8, 1, NULL, 0),
(100, 1, 'QOLS00100', 'Melyra 200/200 SC 24 X 250 ml', 'Fungisida Melyra® 200/200SC merupakan fungisida dengan 2 bahan aktif Mefentrifluconazole 200g/l dan Piraklostrobin 200g/l untuk perlindungan tanaman jagung terhadap penyakit yang diakibatkan jamur secara lebih efektif dan meningkatkan hasil panen lebih maksimal.\nBahan Aktif: Mefentriflukonazol 200 g/L + Piraklostrobin 200 g/L\r\nIsi Bersih: 250 ml\r\n', 'MELYRA_250ML.jpg', 250000, 240000, 232500, 1000, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 345.8, 1, NULL, 0),
(101, 9, 'QOLS00101', 'Metindo 25 WP 10 X 10 X 100 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 100 ml\r\n', 'METINDO_25WP_100GRAM.jpg', 15750, 15300, 15000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 116.5, 1, NULL, 0),
(102, 9, 'QOLS00102', 'Metindo 25 WP 40 X 250 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 250 ml\r\n', 'METINDO_25WP_250GRAM.jpg', 38063, 36975, 36250, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 300, 1, NULL, 0),
(103, 9, 'QOLS00103', 'Metindo 25 WP 40 X 500 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 500 ml\r\n', 'METINDO_25WP_500GRAM.jpg', 71925, 69870, 68500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 603, 1, NULL, 0),
(104, 9, 'QOLS00104', 'Metindo 40 SP 10 X 10 X 100 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 100 gr', 'METINDO_40SP_100GRAM.jpg', 23888, 23205, 22750, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 116.5, 1, NULL, 0),
(105, 9, 'QOLS00105', 'Metindo 40 SP 20 X 800 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 800 gr', 'METINDO_40SP_800GRAM.jpg', 168000, 163200, 160000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(106, 9, 'QOLS00106', 'Metindo 40 SP 40 X 200 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 200 gr\r\n', 'METINDO_40SP_200GRAM.jpg', 45413, 44115, 43250, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 257.5, 1, NULL, 0),
(107, 9, 'QOLS00107', 'Metindo 40 SP 40 X 400 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 400 gr', 'METINDO_40SP_400GRAM.jpg', 89250, 86700, 85000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 467.75, 1, NULL, 0),
(108, 2, 'QOLS00108', 'Metsulindo Plus 80 WP 8 X 25 X 40 gr', 'Herbisida sistemik selektif pra tumbuh dan purna tumbuh, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem untuk mengendalikan gulma berdaun lebar dan teki pada pertanaman padi sawah.\nBahan Aktif: 2,4-D natrium 76% (setara dengan 2,4-D 69%), metil metsulfuron 2%, etil klorimuron 2%\r\nIsi Bersih: 40 gram\r\n', 'METSULINDO_PLUS_40GRAM.jpg', 9030, 8772, 8600, 1000, 0, 'Pcs', 'Pcs', 'Box', '200', '1', 55, 1, NULL, 0),
(109, 9, 'QOLS00109', 'Minecto Xtra 200/200 SC 100 X 50 ml', 'Minecto Xtra merupakan Insektisida racun kontak, lambung dan penghambat pertumbuhan serangga berbentuk pekatan suspensi, berwarna putih, untuk mengendalikan hama pada cabai, jagung, dan tomat. \nBahan Aktif: 200 g/l lufenuron +200 g/l\" siantraniliprol\"\r\nKemasan : 50 ml\r\n', 'MINECTO_XTRA_50ML.jpg', 120750, 117300, 115000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 1, 1, NULL, 0),
(110, 9, 'QOLS00110', 'Minecto Xtra 200/200 SC 50 X 100 ml', 'Minecto Xtra merupakan Insektisida racun kontak, lambung dan penghambat pertumbuhan serangga berbentuk pekatan suspensi, berwarna putih, untuk mengendalikan hama pada cabai, jagung, dan tomat. \nBahan Aktif: 200 g/l lufenuron +200 g/l\" siantraniliprol\"\r\nKemasan : 100 ml\r\n', 'MINECTO_XTRA_100ML.jpg', 243600, 236640, 232000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 150, 1, NULL, 0),
(111, 9, 'QOLS00111', 'Mition 500 EC 15 X 1 ltr', 'Mition 500 EC Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning, untuk mengendalikan hama pada tanaman cabai.\nBahan Aktif: etion 500 g/l\r\nIsi Bersih: 1 Liter\r\n', 'MITION_500EC_1LITER.jpg', 246750, 239700, 235000, 1000, 0, 'Pcs', 'Pcs', 'Box', '15', '1', 1, 1, NULL, 0),
(112, 9, 'QOLS00112', 'Mition 500 EC 20 X 500 ml', 'Mition 500 EC Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning, untuk mengendalikan hama pada tanaman cabai.\nBahan Aktif: etion 500 g/l\r\nIsi Bersih: 500 ml\r\n', 'MITION_500EC_500ML.jpg', 126000, 122400, 120000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 640, 1, NULL, 0),
(113, 9, 'QOLS00113', 'Movento Energy 240 SC 50 X 100 ml', 'Movento Energy 240 SC Insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi putih keabu-abuan untuk mengendalikan hama pada tanaman apel, bawang merah, cabai, jambu biji, jeruk, kentang, kopi, kubis, mangga, melon, rambutan, semangka, tembakau dan tomat\nBahan aktif : Imidakloprid 120 g/ℓ + Spirotetramat 120 g/ℓ\r\nIsi Bersih: 100 ml\r\n', 'MOVENTO_ENERGY_100ML.jpg', 110775, 107610, 105500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 152, 1, NULL, 0),
(114, 1, 'QOLS00114', 'Nativo 75 WG 16 X 20 X 12.5 gr', 'Nativo® adalah fungisida sistemik yang bersifat protektif, preventif, kuratif dan eradikatif berbentuk butiran yang dapat didispersikan dalam air berwarna putih untuk mengendalikan penyakit pada tanaman anggrek, apel, bawang merah, cabai, jagung, jeruk, kacang hijau, kacang tanah, kacang panjang, kakao, karet, krisan, kedelai, kopi, mangga, melon, mentimun, padi, pembibitan kelapa sawit, pisang, semangka, teh, tembakau, dan tomat.\nBahan aktif : Trifloksistrobin 25%  + Tebukonazol 50%\r\nIsi Bersih: 12.5 gr\r\n', 'NATIVO_75WP_12,5GRAM.jpg', 17850, 17340, 17000, 1000, 0, 'Pcs', 'Pcs', 'Box', '320', '1', 18.8, 1, NULL, 0),
(115, 9, 'QOLS00115', 'Nemaguard 10 GR 10 X 1 kg', 'NEMAGUARD 10 GR Insektisida racun kontak dan lambung, berbentuk butiran, berwarna hijau, untuk mengendalikan hama ulat tanah Agrotis ipsilon pada tanaman kentang.\nBahan Aktif: oksamil 10 %\r\nIsi Bersih: 1 Kilogram\r\n', 'NEMAGUARD_10GR_1KG.jpg', 92400, 89760, 88000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(116, 9, 'QOLS00116', 'Nemaguard 10 GR 20 X 500 gr', 'NEMAGUARD 10 GR Insektisida racun kontak dan lambung, berbentuk butiran, berwarna hijau, untuk mengendalikan hama ulat tanah Agrotis ipsilon pada tanaman kentang.\nBahan Aktif: oksamil 10 %\r\nIsi Bersih: 500 Gram\r\n', 'NEMAGUARD_10GR_500GRAM.jpg', 49875, 48450, 47500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(117, 2, 'QOLS00117', 'Neocron 80 OL 15 X 1 ltr', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 1 Liter', 'NEOCRON_80OL_1LITER.jpg', 341250, 331500, 325000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(118, 2, 'QOLS00118', 'Neocron 80 OL 20 X 250 ml', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 250 ml', 'NEOCRON_80OL_250ML.jpg', 90825, 88230, 86500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 327.5, 1, NULL, 0),
(119, 2, 'QOLS00119', 'Neocron 80 OL 20 X 500 ml', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 500 ml\r\n', 'NEOCRON_80OL_500ML.jpg', 173250, 168300, 165000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 612.5, 1, NULL, 0),
(120, 1, 'QOLS00120', 'Orondis Opti 6/400 SC 20 X 500 ml', 'Orondis Opti merupakan Fungisida sistemik yang berbentuk pekatan suspensi, berwarna putih untuk mengendalikan penyakit pada tanaman melon, semangka, timun dan tomat.\nBahan Aktif: 400 g/lklorotalonil + 6 g/l\"oksatiapiprolin\"\r\nKemasan : 500 ml\r\n', 'ORONDIS_OPTI_500ML.jpg', 168000, 163200, 160000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(121, 2, 'QOLS00121', 'Paket Convey 336 SC 10 X 40 ml', 'Convey® adalah herbisida sistemik purna tumbuh berbentuk pekatan suspensi berwarna cokelat muda yang aman untuk tanaman dan fleksibel dalam waktu aplikasinya dibanding dengan herbisida sejenis, sehingga melindungi lebih lama.\nBahan Aktif: Topramezon 336g/l\r\nIsi Bersih: 40 ml\r\n', '-', 343350, 333540, 327000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(122, 2, 'QOLS00122', 'Paket Convey 336 SC 20 X 20 ml', 'Convey® adalah herbisida sistemik purna tumbuh berbentuk pekatan suspensi berwarna cokelat muda yang aman untuk tanaman dan fleksibel dalam waktu aplikasinya dibanding dengan herbisida sejenis, sehingga melindungi lebih lama.\nBahan Aktif: Topramezon 336g/l\r\nIsi Bersih: 20 ml\r\n', '-', 203175, 197370, 193500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 955, 1, NULL, 0),
(123, 9, 'QOLS00123', 'Pegasus 500 SC 50 X 80 ml', 'Pegasus merupakan Insektisida dan akarisida racun kontak dan lambung, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air, untuk mengendalikan hama serangga pada tanaman apel, bawang merah, cabai, kentang, kubis, semangka dan tomat.\nBahan Aktif: 500 g/l Diafenthiuron\r\nKemasan : 80 ml\r\n', 'PEGASUS_500SC_80ML.jpg', 85575, 83130, 81500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 119, 1, NULL, 0),
(124, 9, 'QOLS00124', 'Plenum 50 WG 12 X 10 X 25 gr', 'Plenum merupakan Insektisida sistemik yang bersifat menghambat aktivitas makan serangga, berbentuk butiran berwarna kecoklatan yang dapat disuspensikan dalam air untuk mengendalikan hama wereng coklat, wereng punggung putih, wereng hijau, kepinding tanah dan walang sangit pada tanaman padi.\nBahan Aktif: 50% pimetrozin\r\nKemasan : 25 gram\r\n', 'PLENUM_50WG_100GRAM.jpg', 36750, 35700, 35000, 1000, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 40.4, 1, NULL, 0),
(125, 9, 'QOLS00125', 'Plenum 50 WG 50 X 100 gr', 'Plenum merupakan Insektisida sistemik yang bersifat menghambat aktivitas makan serangga, berbentuk butiran berwarna kecoklatan yang dapat disuspensikan dalam air untuk mengendalikan hama wereng coklat, wereng punggung putih, wereng hijau, kepinding tanah dan walang sangit pada tanaman padi.\nBahan Aktif: 50% pimetrozin\r\nKemasan : 100 gram\r\n', 'PLENUM_50WG_25GRAM.jpg', 135975, 132090, 129500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 141, 1, NULL, 0),
(126, 1, 'QOLS00126', 'Previcur N 722SL 100 X 100 ml', 'Previcur® N 722 SL Fungisida sistemik berbentuk larutan dalam air berwarna kekuning-kuningan yang ditranslokasikan ke seluruh bagian tanaman untuk mengendalikan penyakit pada tanaman bawang merah, cabai, kentang, kubis, melon, pinus, tembakau dan tomat.\nBahan aktif : Propamokarb hidroklorida 722 g/l\r\nIsi Bersih: 100 ml\r\n', 'PREVICUR_N_722SL_100ML.jpg', 37800, 36720, 36000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 144.2, 1, NULL, 0),
(127, 1, 'QOLS00127', 'Previcur N 722SL 20 X 500 ml', 'Previcur® N 722 SL Fungisida sistemik berbentuk larutan dalam air berwarna kekuning-kuningan yang ditranslokasikan ke seluruh bagian tanaman untuk mengendalikan penyakit pada tanaman bawang merah, cabai, kentang, kubis, melon, pinus, tembakau dan tomat.\nBahan aktif : Propamokarb hidroklorida 722 g/l\r\nIsi Bersih: 500 ml\r\n', 'PREVICUR_N_722SL_500ML.jpg', 170888, 166005, 162750, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 649, 1, NULL, 0),
(128, 9, 'QOLS00128', 'Regent 50 SC Red 24 X 250 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'REGENT_RED_50SC_250ML.jpg', 101850, 98940, 97000, 1000, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 318.8, 1, NULL, 0),
(129, 9, 'QOLS00129', 'Regent 50 SC Red 48 X 100 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 100 ml\r\n', 'REGENT_RED_50SC_50ML.jpg', 44625, 43350, 42500, 1000, 0, 'Pcs', 'Pcs', 'Box', '48', '1', 133.3, 1, NULL, 0),
(130, 9, 'QOLS00130', 'Regent 50 SC Red 80 X 50 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 50 ml\r\n', 'REGENT_RED_50SC_100ML.jpg', 23625, 22950, 22500, 1000, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 1, 1, NULL, 0),
(131, 1, 'QOLS00131', 'Remazole-P 490 EC 20 X 400 ml', 'Remazole P 490 EC adalah fungisida sistemik dalam bentuk pekatan yang dapat diemulsikan (EC) untuk mengendalikan berbagai penyakit jamur pada tanaman seperti padi, bawang merah, kedelai, dan mangga. Fungisida ini mengandung dua bahan aktif, yaitu Prokloraz (400 g/L) dan Propikonazol (90 g/L). Remazole P 490 EC bekerja secara protektif, kuratif, dan eradikatif, efektif untuk melawan penyakit seperti bercak daun, karat daun, hawar pelepah, dan bercak ungu.\nBahan Aktif:\r\nProkloraz (400 g/L) dan Propikonazol (90 g/L).\r\nIsi Bersih: 400 ml\r\n', 'REMAZOLE_P_490EC_400ML.jpg', 350175, 340170, 333500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 567.5, 1, NULL, 0),
(132, 1, 'QOLS00132', 'Remazole-P 490 EC 40 X 250 ml', 'Remazole P 490 EC adalah fungisida sistemik dalam bentuk pekatan yang dapat diemulsikan (EC) untuk mengendalikan berbagai penyakit jamur pada tanaman seperti padi, bawang merah, kedelai, dan mangga. Fungisida ini mengandung dua bahan aktif, yaitu Prokloraz (400 g/L) dan Propikonazol (90 g/L). Remazole P 490 EC bekerja secara protektif, kuratif, dan eradikatif, efektif untuk melawan penyakit seperti bercak daun, karat daun, hawar pelepah, dan bercak ungu.\nBahan Aktif:\r\nProkloraz (400 g/L) dan Propikonazol (90 g/L).\r\nIsi Bersih: 250 ml\r\n', 'REMAZOLE_P_490EC_250ML.jpg', 227850, 221340, 217000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 375, 1, NULL, 0),
(133, 1, 'QOLS00133', 'Revus Opti 440 SC 20 X 250 ml', 'Revus Opti merupakan Fungisida protektif yang bersifat sistemik dan kontak, berbentuk pekatan suspensi, berwarna putih keabu-abuan, untuk mengendalikan penyakit secara preventif dan kuratif pada tanaman bawang merah, cabai, jeruk, kakao, kentang, mentimun, melon, semangka, tembakau dan tomat. \nBahan Aktif:\r\n40 g/l mandipropamid\r\n400 g/l klorotalonil\r\nKemasan : 250 ml\r\n', 'REVUS_OPTI_440SC_250ML.jpg', 110250, 107100, 105000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 355, 1, NULL, 0),
(134, 2, 'QOLS00134', 'Ricestar Xtra 89 OD 100 X 100 ml', 'Ricestar® Xtra 89 OD Herbisida sistemik purna tumbuh berbentuk larutan dalam minyak berwarna putih keabu-abuan untuk mengendalikan gulma pada pertanaman padi.\nBahan aktif : Fenoksaprop-p-etil 69 g/ℓ + Etoksisulfuron 20 g/l\r\nIsi Bersih: 100 ml\r\n', 'RICESTAR_XTRA_100ML.jpg', 62475, 60690, 59500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 137, 1, NULL, 0),
(135, 2, 'QOLS00135', 'Ricestar Xtra 89 OD 40 X 250 ml', 'Ricestar® Xtra 89 OD Herbisida sistemik purna tumbuh berbentuk larutan dalam minyak berwarna putih keabu-abuan untuk mengendalikan gulma pada pertanaman padi.\nBahan aktif : Fenoksaprop-p-etil 69 g/ℓ + Etoksisulfuron 20 g/l\r\nIsi Bersih: 250 ml\r\n', 'RICESTAR_XTRA_250ML.jpg', 147000, 142800, 140000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 326.25, 1, NULL, 0),
(136, 1, 'QOLS00136', 'Ridomil Gold 350 ES 4 X 20 X 12.5 ml', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 12,5 ml\r\n', 'RIDOMIL_GOLD_350ES_12,5ML.jpg', 22838, 22185, 21750, 1000, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 37.5, 1, NULL, 0),
(137, 1, 'QOLS00137', 'Ridomil Gold MZ 4/64 WG 100 X 100 gr', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 100 gram\r\n', 'RIDOMIL_GOLD_100GRAM.jpg', 38850, 37740, 37000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 121, 1, NULL, 0),
(138, 1, 'QOLS00138', 'Ridomil Gold MZ 4/64 WG 20 X 500 gr', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 500 gram\r\n', 'RIDOMIL_GOLD_500GRAM.jpg', 180600, 175440, 172000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 592.5, 1, NULL, 0),
(139, 1, 'QOLS00139', 'Ridomil Gold MZ 4/64 WG 40 X 250 gr', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 250 gram\r\n', 'RIDOMIL_GOLD_250GRAM.jpg', 92400, 89760, 88000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 291.3, 1, NULL, 0),
(140, 9, 'QOLS00140', 'Rotraz 200 EC 20 X 500 ml', 'Rotraz 200 EC Insektisida dan akarisida racun kontak dan pernafasan, berbentuk pekatan yang dapat diemulsikan dalam air, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman apel dan cabai.\nBahan Aktif: amitraz 200 g/l\r\nIsi Bersih: 500 ml\r\n', 'ROTRAZ_200EC_500ML.jpg', 99750, 96900, 95000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 575, 1, NULL, 0),
(141, 9, 'QOLS00141', 'Rotraz 200 EC 50 X 100 ml', 'Rotraz 200 EC Insektisida dan akarisida racun kontak dan pernafasan, berbentuk pekatan yang dapat diemulsikan dalam air, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman apel dan cabai.\nBahan Aktif: amitraz 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'ROTRAZ_200EC_100ML.jpg', 28350, 27540, 27000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 141, 1, NULL, 0),
(142, 2, 'QOLS00142', 'Rumpas 110 EW 100 X 100 ml', 'Rumpas® 110 EW Herbisida kontak dan sistemik purna tumbuh berbentuk pekatan emulsi minyak dalam air berwarna putih untuk mengendalikan gulma pada pertanaman bawang merah, cabai, kacang hijau, kacang panjang, kacang tanah, kedelai, ketimun, nanas, padi sawah dan tebu.\nBahan aktif : Fenoksaprop -p-etil 110 g/l\r\nIsi Bersih: 100 ml\r\n', 'RUMPAS_110EW_100ML.jpg', 43313, 42075, 41250, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 136.3, 1, NULL, 0),
(143, 2, 'QOLS00143', 'Rumpas 110 EW 40 X 250 ml', 'Rumpas® 110 EW Herbisida kontak dan sistemik purna tumbuh berbentuk pekatan emulsi minyak dalam air berwarna putih untuk mengendalikan gulma pada pertanaman bawang merah, cabai, kacang hijau, kacang panjang, kacang tanah, kedelai, ketimun, nanas, padi sawah dan tebu.\nBahan aktif : Fenoksaprop -p-etil 110 g/l\r\nIsi Bersih: 250 ml\r\n', 'RUMPAS_110EW_250ML.jpg', 103425, 100470, 98500, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 322.5, 1, NULL, 0),
(144, 1, 'QOLS00144', 'Score 250 EC 40 X 250 ml', 'Score merupakan Fungisida sistemik berbentuk pekatan yang dapat diemulsikan, berwarna coklat kekuning-kuningan sampai coklat tua untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jagung, jarak pagar, jeruk, kacang panjang, kedelai, kelapa sawit, kentang, mangga, padi, semangka, tembakau, dan tomat. \nBahan Aktif: 250 g/l difenokonazol\r\nKemasan : 250 ml\r\n', 'SCORE_250EC_250ML.jpg', 173513, 168555, 165250, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 312, 1, NULL, 0),
(145, 1, 'QOLS00145', 'Score 250 EC 50 X 80 ml', 'Score merupakan Fungisida sistemik berbentuk pekatan yang dapat diemulsikan, berwarna coklat kekuning-kuningan sampai coklat tua untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jagung, jarak pagar, jeruk, kacang panjang, kedelai, kelapa sawit, kentang, mangga, padi, semangka, tembakau, dan tomat. \nBahan Aktif: 250 g/l difenokonazol\r\nKemasan : 80 ml\r\n', 'SCORE_250EC_80ML.jpg', 58013, 56355, 55250, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 110.6, 1, NULL, 0),
(146, 1, 'QOLS00146', 'Seltima 100 CS 20 X 500 ml', 'Seltima® 100 CS adalah fungisida dengan formulasi inovatif yang bekerja secara sistemik, bekerja protektif dan kuratif berbentuk mikrokapsul dalam pekatan yang dapat disuspensikan berwarna putih untuk mengendalikan penyakit pada tanaman padi. Seltima® juga memiliki efek Agcelence yang berperan dalam pengisian gabah sehingga gabah terisi maksimal dan mengurangi jumlah gabah kosong.\nBahan aktif: Piraklostrobin 100 g/l\r\nIsi Bersih: 500 ml\r\n', 'SELTIMA_100CS_500ML.jpg', 192675, 187170, 183500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 600, 1, NULL, 0),
(147, 1, 'QOLS00147', 'Seltima 100 CS 24 X 250 ml', 'Seltima® 100 CS adalah fungisida dengan formulasi inovatif yang bekerja secara sistemik, bekerja protektif dan kuratif berbentuk mikrokapsul dalam pekatan yang dapat disuspensikan berwarna putih untuk mengendalikan penyakit pada tanaman padi. Seltima® juga memiliki efek Agcelence yang berperan dalam pengisian gabah sehingga gabah terisi maksimal dan mengurangi jumlah gabah kosong.\nBahan aktif: Piraklostrobin 100 g/l\r\nIsi Bersih: 250 ml\r\n', 'SELTIMA_100CS_250ML.jpg', 104475, 101490, 99500, 1000, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 333, 1, NULL, 0),
(148, 9, 'QOLS00148', 'Simodis 100 DC 50 X 100 ml', 'Simodis merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat didispersikan, berwarna coklat, untuk mengendalikan hama pada tanaman bawang merah, cabai, kubis dan tomat.\nBahan Aktif:\r\n100 g/l isosikloseram \r\nKemasan : 100 ml\r\n', 'SIMODIS_100DC_100ML.jpg', 134400, 130560, 128000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 149, 1, NULL, 0),
(149, 9, 'QOLS00149', 'Sivanto Prime 200 SL 100 X 100 ml', 'Sivanto Prime 200 SL Insektisida sistemik berbentuk larutan dalam air, berwarna kuning kecoklatan / merah, untuk mengendalikan hama pada tanaman cabai, jeruk, tembakau, terong, dan tomat\nBahan aktif : Flupiradifuron 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'SIVANTO_PRIME_100ML.jpg', 64050, 62220, 61000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 154.5, 1, NULL, 0),
(150, 15, 'QOLS00150', 'Stardon 60 WP 10 X 8 X 100 gr', 'Stardon 60 WP Moluskisida racun kontak berbentuk tepung yang dapat disuspensikan, berwarna putih, untuk mengendalikan siput murbei (Pomacea canaliculata) pada tanaman padi sawah.\nBahan Aktif: fentin asetat 60%\r\nIsi Bersih: 100 Gram\r\n', 'STARDON_60WP_100GRAM.jpg', 55650, 54060, 53000, 1000, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 129, 1, NULL, 0),
(151, 9, 'QOLS00151', 'Symphony Plus 32 X 250 ml', 'SYMPHONY 100 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, dan Kubis.\nBahan Aktif : Piridalil 100 g/L\r\nIsi Bersih: 250 ml\r\n', 'SYMPHONY_PLUS_250ML.jpg', 346500, 336600, 330000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 656.3, 1, NULL, 0),
(152, 9, 'QOLS00152', 'Symphony Plus 40 X 100 ml', 'SYMPHONY 100 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, dan Kubis.\nBahan Aktif : Piridalil 100 g/L\r\nIsi Bersih: 100 ml\r\n', 'SYMPHONY_PLUS_100ML.jpg', 141750, 137700, 135000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 305, 1, NULL, 0),
(153, 1, 'QOLS00153', 'Topsindo 70 WP 20 X 500 gr', 'Topsindo 70 WP Fungisida kontak dan sistemik berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman padi dan tembakau.\nBahan Aktif: metil tiofanat 70%\r\nIsi Bersih: 500 ml\r\n', 'TOPSINDO_70WP_500GRAM.jpg', 102900, 99960, 98000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 597.5, 1, NULL, 0),
(154, 9, 'QOLS00154', 'Trigard 75 WP 10 X 10 X 50 gr', 'Trigard® 75 WP merupakan insektisida sistemik penghambat pertumbuhan serangga, berbentuk tepung yang dapat disuspensikan berwarna putih kecoklat-coklatan, digunakan untuk mengendalikan hama pada tanaman bawang merah, kacang panjang, kentang, dan tomat. \nBahan Aktif: 75% siromazin\r\nKemasan : 50 gram\r\n', 'TRIGARD_75WP_50GRAM.jpg', 211575, 205530, 201500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 67.7, 1, NULL, 0),
(155, 9, 'QOLS00155', 'Trigard 75 WP 12 X 10 X 25 gr', 'Trigard® 75 WP merupakan insektisida sistemik penghambat pertumbuhan serangga, berbentuk tepung yang dapat disuspensikan berwarna putih kecoklat-coklatan, digunakan untuk mengendalikan hama pada tanaman bawang merah, kacang panjang, kentang, dan tomat. \nBahan Aktif: 75% siromazin\r\nKemasan : 25 gram\r\n', 'TRIGARD_75WP_25GRAM.jpg', 110775, 107610, 105500, 1000, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 40, 1, NULL, 0),
(156, 2, 'QOLS00156', 'Unibro 500/50 SC 20 X 250 ml', 'UNIBRO 500/50 EC Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi, berwarna coklat muda, untuk mengendalikan gulma berdaun lebar, gulma golongan rumput dan teki pada budidaya tanaman jagung.\nBahan Aktif: atrazin 500 g/l mesotrion 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'UNIBRO_250ML.jpg', 68250, 66300, 65000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 327.5, 1, NULL, 0),
(157, 2, 'QOLS00157', 'Unibro 500/50 SC 20 X 500 ml', 'UNIBRO 500/50 EC Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi, berwarna coklat muda, untuk mengendalikan gulma berdaun lebar, gulma golongan rumput dan teki pada budidaya tanaman jagung.\nBahan Aktif: atrazin 500 g/l mesotrion 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'UNIBRO_500ML.jpg', 131250, 127500, 125000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 612.5, 1, NULL, 0),
(158, 9, 'QOLS00158', 'Vayego 200 SC 50 X 100 ml', 'Vayego® 200 SC Insektisida sistemik, racun kontak dan lambung berbentuk pekatan suspensi, berwarna putih sampai kecoklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jagung, kelapa sawit dan kubis.\nBahan aktif: Tetraniliprol 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'VAYEGO_200SC_100ML.jpg', 216300, 210120, 206000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 146, 1, NULL, 0),
