(392, 13, 'QOLS00382', 'Gibas 240 SL 4 X 5 ltr', 'kemasan 1 liter, 20 liter, 5 liter', 'GIBAS_240SL_5LITER.jpg', 144375, 140250, 137500, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(393, 13, 'QOLS00383', 'Gibraz 20/125 OD 100 X 80 ml', '', 'GIBRAZ_80ML.jpg', 54600, 53040, 52000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
