(395, 13, 'QOLS00385', 'Gibraz 20/125 OD 50 X 200 ml', '', 'GIBRAZ_200ML.jpg', 131250, 127500, 125000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(396, 13, 'QOLS00386', 'Greenforce 12 X 1 ltr', '', 'GREENFORCE_1LITER.jpg', 136500, 132600, 130000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(397, 13, 'QOLS00387', 'Greenforce 20 X 500 ml', 'greenforce adalah ZAT (Zat Pengatur Tumbuh) formulasi daun berbasis asam amino konsentrasi tinggi yang berfungsi untuk merangsang pertumbuhan daun, meningkatkan kehijauan (klorofil), serta memperbaiki ketebalan dan tekstur daun. Cocok digunakan pada berbagai jenis tanaman pertanian dan hortikultura, terutama saat fase vegetatif atau kondisi tanaman stres. kemasan 500ml, 30ml, 1liter. bahan aktif Asam Amino ≥ 47,1%, C-Organik ≥ 32,27%, N-Organik ≥ 2,4%, pH: 5–8. Aplikasikan 3 -4 kali permusim, 1minggu setelah tanam saat pembentukan anakan, bunting dan pembungaan untuk tanaman padi. 3-4 kali per musim (pindah tanam, awal pembungaan, pembungaan dan pembentukan buah) untuk sayuran, buah - buahan, palawija dan tanaman perkebunan. 3-4 kali per musim (pindah tanam, awal pembungaan dan selama pembungaan untuk tanaman hias)', 'GREENFORCE_500ML.jpg', 70350, 68340, 67000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(398, 13, 'QOLS00388', 'Greenforce 80 X 30 ml', '', 'GREENFORCE_30ML.jpg', 9450, 9180, 9000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(399, 13, 'QOLS00389', 'Jagung Manis Panglima F1 40 X 1750 biji', '', 'JAGUNGMANIS_PANGLIMA_F1_1750BIJI.jpg', 97650, 94860, 93000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(400, 13, 'QOLS00390', 'Kaliandra 482 EC 10 X 1 ltr (AGM)', '', 'KALIANDRA_482EC_1LITER.jpg', 181125, 175950, 172500, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
(401, 13, 'QOLS00391', 'Kaliandra 482 EC 30 X 400 ml', 'kaliandra adalah insektisida racun kontak, lambung dan pernafasan berbentuk pekatan yang dapat diemulsikan untuk mengendalikan hama pada tanaman yaitu kutu daun, bahan aktif klorpirifos 482 g/l. kemasan 400ml, 200ml, 80 ml, 1 liter', 'KALIANDRA_482EC_400ML.jpg', 77700, 75480, 74000, 1000, 0, 'Pcs', 'Pcs', 'Box', '-', '1', 0, 1, NULL, 0),
